-- SECTION B: Pack 02 function replacements (no DELETE inside) and the team_history view
-- =====================================================================================================================================
CREATE OR REPLACE FUNCTION private.log_result_revision(p_comp uuid, p_entry uuid, p_action text, p_old_place integer, p_old_points numeric, p_new_place integer, p_new_points numeric, p_reason text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  insert into public.result_revisions (competition_id, entry_id, revision, action, old_place, old_points, new_place, new_points, reason, actor)
  select p_comp, p_entry, coalesce(max(revision), 0) + 1, p_action, p_old_place, p_old_points, p_new_place, p_new_points, p_reason, auth.uid()
  from public.result_revisions where competition_id = p_comp and entry_id = p_entry
$function$;

CREATE OR REPLACE FUNCTION private.result_revisions_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin raise exception 'the result revision log is append-only' using errcode = '42501'; end $function$;

CREATE OR REPLACE FUNCTION public.correct_result(p_competition uuid, p_entry uuid, p_place integer, p_points numeric, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event uuid; v_old public.results;
begin
  v_event := private.event_of_competition(p_competition);
  if v_event is null then raise exception 'competition not found' using errcode = 'P0002'; end if;
  if not private.is_organizer(v_event) then raise exception 'only an organizer can correct an official result' using errcode = '42501'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'say why the result is being corrected' using errcode = '22023'; end if;
  if p_place is null or p_place < 1 or p_points is null or p_points < 0 then raise exception 'place must be 1 or more and points 0 or more' using errcode = '22023'; end if;
  select * into v_old from public.results where competition_id = p_competition and entry_id = p_entry for update;
  if not found then raise exception 'there is no official result for that entry' using errcode = 'P0002'; end if;
  update public.results set final_place = p_place, points = p_points where id = v_old.id;
  perform private.log_result_revision(p_competition, p_entry, 'corrected', v_old.final_place, v_old.points, p_place, p_points, btrim(p_reason));
  perform private.audit(v_event, 'result.corrected', p_competition::text, jsonb_build_object('entry', p_entry, 'reason', btrim(p_reason)));
end $function$;

CREATE OR REPLACE FUNCTION private.snapshot_entry_team()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.team_id is null then new.team_name_at_event := null; return new; end if;
  if tg_op = 'INSERT' or (new.team_id is distinct from old.team_id and coalesce(current_setting('bos.merging', true), '') <> 'on') then
    select t.name into new.team_name_at_event from public.teams t where t.id = new.team_id;
  end if;
  return new;
end $function$;

revoke execute on function private.log_result_revision(uuid, uuid, text, integer, numeric, integer, numeric, text) from public, anon, authenticated;
grant execute on function public.correct_result(uuid, uuid, integer, numeric, text) to authenticated;

-- team_history: the name used at the event, and the team as it is now (adds three columns at the end; existing columns unchanged)
create or replace view public.team_history with (security_invoker = true) as
 SELECT e.team_id, ev.id AS event_id, ev.slug AS event_slug, ev.name AS event_name, ev.starts_on, k.id AS competition_id, k.name AS competition_name, k.ruleset, r.final_place, r.points,
        private.is_synthetic('event', ev.id) AS synthetic,
        coalesce(e.team_name_at_event, t.name) AS team_name_at_event, t.name AS team_current_name, t.slug AS team_current_slug
   FROM ((((results r JOIN entries e ON ((e.id = r.entry_id))) JOIN competitions k ON ((k.id = r.competition_id))) JOIN events ev ON ((ev.id = k.event_id)))
        LEFT JOIN teams t ON ((t.id = e.team_id)))
  WHERE e.team_id IS NOT NULL;

-- =====================================================================================================================================
-- SECTION C: statements that DROP or replace something (schema/privileges only; no row is removed)
-- =====================================================================================================================================
-- C1 (Pack 01) the obsolete "organizer of any event" helper. Inventory: no function, policy or view refers to it (pg_depend and bodies checked).
drop function if exists private.is_any_organizer();

-- C2 (Pack 02) official results are written only through finish_competition / correct_result / void_result (all logged).
--    Removes the policy that let any organizer of the event insert/update/delete results directly, and the matching table privileges.
drop policy if exists results_organizer_write on public.results;
revoke insert, update, delete on public.results from authenticated;

-- C3 (Pack 03) event_staff accepts the new head_marshal role. Replaces the CHECK constraint only (existing rows are validated, none removed).
do $c3$
begin
  if (select pg_get_constraintdef(oid) from pg_constraint where conrelid = 'public.event_staff'::regclass and conname = 'event_staff_role_check')
     is distinct from $t$CHECK ((role = ANY (ARRAY['organizer'::text, 'head_marshal'::text, 'marshal'::text, 'scorekeeper'::text, 'medic'::text])))$t$ then
    alter table public.event_staff drop constraint if exists event_staff_role_check;
    alter table public.event_staff add constraint event_staff_role_check check (role in ('organizer', 'head_marshal', 'marshal', 'scorekeeper', 'medic'));
  end if;
end $c3$;

-- =====================================================================================================================================
-- SECTION D: Pack 02 functions whose bodies contain DELETE, and the triggers that call them. Creating or replacing them deletes nothing now;
-- the DELETEs run later, only through these controlled paths, and every removed official result is first written to result_revisions.
-- =====================================================================================================================================
CREATE OR REPLACE FUNCTION public.record_tie_decision(p_competition uuid, p_part text, p_order uuid[], p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event uuid; v_part text := coalesce(p_part, ''); v_raw bigint; v_group uuid[]; i int;
begin
  v_event := private.event_of_competition(p_competition);
  if v_event is null then raise exception 'competition not found' using errcode = 'P0002'; end if;
  if not private.is_organizer(v_event) then raise exception 'only an organizer can decide a tie' using errcode = '42501'; end if;
  if char_length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'say why this order was chosen' using errcode = '22023'; end if;
  if p_order is null or cardinality(p_order) < 2 then raise exception 'list the tied entries in the order they should finish' using errcode = '22023'; end if;
  perform 1 from public.competitions where id = p_competition for update;
  select g.raw_rank into v_raw from private.group_ranks(p_competition) g where g.part = v_part and g.ent = p_order[1];
  if v_raw is null then raise exception 'that entry has no standing in this pool yet' using errcode = '22023'; end if;
  select array_agg(g.ent) into v_group from private.group_ranks(p_competition) g where g.part = v_part and g.raw_rank = v_raw;
  if cardinality(v_group) < 2 then raise exception 'there is no tie to decide here' using errcode = '22023'; end if;
  if not (v_group @> p_order and p_order @> v_group and cardinality(p_order) = cardinality(v_group)) then
    raise exception 'list exactly the tied entries, each once' using errcode = '22023'; end if;
  delete from public.pool_tie_decisions where competition_id = p_competition and entry_id = any (v_group);
  for i in 1 .. cardinality(p_order) loop
    insert into public.pool_tie_decisions (competition_id, entry_id, part, rank, note, decided_by) values (p_competition, p_order[i], v_part, i, btrim(p_note), auth.uid());
  end loop;
  perform private.audit(v_event, 'pool.tie_decided', p_competition::text, jsonb_build_object('pool', v_part, 'order', to_jsonb(p_order), 'note', btrim(p_note)));
end $function$;

CREATE OR REPLACE FUNCTION private.clear_tie_decisions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  delete from public.pool_tie_decisions where competition_id = new.competition_id;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.finish_competition(p_competition uuid, p_multiplier_source text DEFAULT 'tournament_structure'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_k public.competitions; v_open int; v_mult numeric; n int := 0; r record; v_old public.results; v_pts numeric;
begin
  select * into v_k from public.competitions where id = p_competition for update;
  if not found then raise exception 'competition not found' using errcode = 'P0002'; end if;
  if not private.is_organizer(v_k.event_id) then raise exception 'only an organizer can finish a competition' using errcode = '42501'; end if;
  if p_multiplier_source is null or p_multiplier_source not in ('tournament_structure', 'league_structure') then
    raise exception 'multiplier source must be tournament_structure or league_structure' using errcode = '22023'; end if;
  if not exists (select 1 from public.matches where competition_id = p_competition) then raise exception 'this competition has no matches' using errcode = 'P0001'; end if;
  select count(*) into v_open from public.matches where competition_id = p_competition and queue_state <> 'final';
  if v_open > 0 then raise exception '% match(es) are not final yet', v_open using errcode = 'P0001'; end if;
  -- Finishing again recomputes from the matches; any change to a stored result is written to result_revisions ('recomputed').
  if exists (select 1 from public.result_revisions where competition_id = p_competition and action = 'corrected')
     and exists (select 1 from public.results where competition_id = p_competition) then
    raise exception 'results were corrected by hand; reopen a match to recompute them, or correct them again' using errcode = 'P0001'; end if;
  if v_k.structure = 'round_robin' and exists (select 1 from private.unresolved_ties(p_competition, 3)) then
    raise exception 'a tie for a medal place is not decided yet; record the order first' using errcode = 'P0001'; end if;
  if v_k.tier is not null then
    select case p_multiplier_source when 'league_structure' then multiplier_league_structure else multiplier_tournament_structure end into v_mult
      from public.ref_tiers where name = v_k.tier;
  end if;

  for r in select c.entry_id, c.final_place, c.base_points from private.compute_places(p_competition) c loop
    v_pts := private.tier_points(r.base_points, v_k.tier, p_multiplier_source);
    select * into v_old from public.results where competition_id = p_competition and entry_id = r.entry_id;
    if not found then
      insert into public.results (competition_id, entry_id, final_place, points) values (p_competition, r.entry_id, r.final_place, v_pts);
      perform private.log_result_revision(p_competition, r.entry_id, 'computed', null, null, r.final_place, v_pts, null);
    elsif v_old.final_place is distinct from r.final_place or v_old.points is distinct from v_pts then
      update public.results set final_place = r.final_place, points = v_pts where id = v_old.id;
      perform private.log_result_revision(p_competition, r.entry_id, 'recomputed', v_old.final_place, v_old.points, r.final_place, v_pts, null);
    end if;
    n := n + 1;
  end loop;
  for v_old in select * from public.results where competition_id = p_competition and entry_id not in (select c.entry_id from private.compute_places(p_competition) c) loop
    perform private.log_result_revision(p_competition, v_old.entry_id, 'superseded', v_old.final_place, v_old.points, null, null, 'entry no longer ranked');
    delete from public.results where id = v_old.id;
  end loop;
  update public.competitions set status = 'finished' where id = p_competition;
  perform private.audit(v_k.event_id, 'competition.finished', p_competition::text,
    jsonb_build_object('entries', n, 'tier', v_k.tier, 'multiplier', v_mult, 'source', p_multiplier_source));
  return n;
end $function$;

CREATE OR REPLACE FUNCTION public.void_result(p_competition uuid, p_entry uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event uuid; v_old public.results;
begin
  v_event := private.event_of_competition(p_competition);
  if v_event is null then raise exception 'competition not found' using errcode = 'P0002'; end if;
  if not private.is_organizer(v_event) then raise exception 'only an organizer can void an official result' using errcode = '42501'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'say why the result is being voided' using errcode = '22023'; end if;
  select * into v_old from public.results where competition_id = p_competition and entry_id = p_entry for update;
  if not found then raise exception 'there is no official result for that entry' using errcode = 'P0002'; end if;
  perform private.log_result_revision(p_competition, p_entry, 'voided', v_old.final_place, v_old.points, null, null, btrim(p_reason));
  delete from public.results where id = v_old.id;
  perform private.audit(v_event, 'result.voided', p_competition::text, jsonb_build_object('entry', p_entry, 'reason', btrim(p_reason)));
end $function$;

CREATE OR REPLACE FUNCTION private.unfinish_competition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_event uuid; r public.results; v_reason text := coalesce(nullif(current_setting('bos.reopen_reason', true), ''), 'a match was reopened or added');
begin
  if tg_op = 'UPDATE' and not (old.queue_state = 'final' and new.queue_state <> 'final') then return new; end if;
  if tg_op = 'INSERT' and new.queue_state = 'final' then return new; end if;
  select event_id into v_event from public.competitions where id = new.competition_id and status = 'finished';
  if found then
    for r in select * from public.results where competition_id = new.competition_id loop
      perform private.log_result_revision(new.competition_id, r.entry_id, 'superseded', r.final_place, r.points, null, null, v_reason);
    end loop;
    delete from public.results where competition_id = new.competition_id;
    update public.competitions set status = 'running' where id = new.competition_id;
    perform private.audit(v_event, 'competition.reopened', new.competition_id::text, jsonb_build_object('match', new.id, 'reason', v_reason, 'results_superseded', true));
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.build_schedule(p_competition uuid, p_matches jsonb, p_mode text, p_draw jsonb DEFAULT NULL::jsonb, p_advance integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_k public.competitions; v_ids jsonb := '{}'::jsonb; v_el jsonb; v_key text; v_id uuid; v_n int := 0; v_existing int; v_final int;
  v_old uuid[]; v_expect uuid[]; v_got uuid[]; v_format text; v_next text;
begin
  select * into v_k from public.competitions where id = p_competition for update;
  if not found then raise exception 'competition not found' using errcode = 'P0002'; end if;
  if not private.is_organizer(v_k.event_id) then raise exception 'only an organizer can build a schedule' using errcode = '42501'; end if;
  if p_mode is null or p_mode not in ('new', 'replace', 'append') then raise exception 'mode must be new, replace or append' using errcode = '22023'; end if;
  if p_matches is null or jsonb_typeof(p_matches) <> 'array' or jsonb_array_length(p_matches) > 400 then raise exception 'send a list of at most 400 planned matches' using errcode = '22023'; end if;
  select count(*), count(*) filter (where queue_state = 'final') into v_existing, v_final from public.matches where competition_id = p_competition;

  if p_mode = 'new' and v_existing > 0 then raise exception 'This competition already has matches. Replace them to start over.' using errcode = 'P0001'; end if;
  if p_mode = 'replace' then
    if v_final > 0 then raise exception 'Some matches are already final. Reopen them before replacing the schedule.' using errcode = 'P0001'; end if;
    select array_agg(id) into v_old from public.matches where competition_id = p_competition;
  end if;
  if p_mode = 'append' then
    if p_advance is null or p_advance < 1 then raise exception 'say how many advance from each pool' using errcode = '22023'; end if;
    if not exists (select 1 from public.matches where competition_id = p_competition and stage = 'pool') then raise exception 'there is no pool play to build a bracket from' using errcode = 'P0001'; end if;
    if exists (select 1 from public.matches where competition_id = p_competition and stage in ('elimination', 'third_place', 'final')) then
      raise exception 'the bracket for this competition was already built' using errcode = 'P0001'; end if;
    if exists (select 1 from public.matches where competition_id = p_competition and stage = 'pool' and queue_state <> 'final') then
      raise exception 'pool play is not finished' using errcode = 'P0001'; end if;
    if v_k.structure <> 'pools_elimination' then update public.competitions set structure = 'pools_elimination' where id = p_competition; end if;
    if exists (select 1 from private.unresolved_ties(p_competition, p_advance)) then
      raise exception 'a pool tie affects who advances; record the order first' using errcode = 'P0001'; end if;
    select array_agg(g.ent order by g.ent) into v_expect from private.group_ranks(p_competition) g where g.lvl = 'p' and g.wrank <= p_advance;
  end if;

  for v_el in select value from jsonb_array_elements(p_matches) loop
    v_key := v_el ->> 'key';
    if v_key is null or v_ids ? v_key then raise exception 'every planned match needs its own key' using errcode = '22023'; end if;
    v_id := gen_random_uuid();
    v_ids := v_ids || jsonb_build_object(v_key, v_id);
    insert into public.matches (id, competition_id, stage, round_label, position, pool, entry_a, entry_b)
    values (v_id, p_competition, v_el ->> 'stage', coalesce(v_el ->> 'round_label', ''), coalesce((v_el ->> 'position')::int, 0), nullif(v_el ->> 'pool', ''),
            nullif(v_el ->> 'a', '')::uuid, nullif(v_el ->> 'b', '')::uuid);
    v_n := v_n + 1;
  end loop;
  for v_el in select value from jsonb_array_elements(p_matches) loop
    v_next := v_el ->> 'next_key';
    if v_next is not null then
      if not (v_ids ? v_next) then raise exception 'planned match % links to unknown match %', v_el ->> 'key', v_next using errcode = '22023'; end if;
      update public.matches set next_match_id = (v_ids ->> v_next)::uuid, next_slot = v_el ->> 'next_slot' where id = (v_ids ->> (v_el ->> 'key'))::uuid;
    end if;
  end loop;

  if p_mode = 'append' then
    select array_agg(distinct x order by x) into v_got
    from (select nullif(e.value ->> 'a', '')::uuid x from jsonb_array_elements(p_matches) e union all select nullif(e.value ->> 'b', '')::uuid from jsonb_array_elements(p_matches) e) s where x is not null;
    if v_got is distinct from v_expect then raise exception 'the bracket does not match the pool standings; reload and try again' using errcode = 'P0001'; end if;
  end if;
  if p_mode = 'replace' and v_old is not null then delete from public.matches where id = any (v_old); end if;

  if p_mode <> 'append' and p_draw is not null then
    v_format := p_draw ->> 'format';
    update public.competitions set
      draw_seed = case when p_draw ->> 'mode' = 'random' then (p_draw ->> 'seed')::int end,
      draw_mode = p_draw ->> 'mode', draw_algorithm = p_draw ->> 'algorithm', drawn_at = now(),
      structure = case v_format when 'pools' then 'pools_elimination' when 'single_elimination' then 'elimination' when 'round_robin' then 'round_robin' else structure end
    where id = p_competition;
  end if;
  perform private.audit(v_k.event_id, 'schedule.built', p_competition::text, jsonb_build_object('mode', p_mode, 'matches', v_n, 'draw', p_draw, 'advance', p_advance));
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.merge_teams(p_keep uuid, p_remove uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_keep public.teams; v_remove public.teams;
  n_entries int; n_regs int; n_regcomps int; n_fighters int; n_roles int; n_affil int; n_members int; n_hosts int;
begin
  if not (private.can_admin_team(p_keep) and private.can_admin_team(p_remove)) then raise exception 'only a platform administrator, or an organization administrator for both teams, can merge teams' using errcode = '42501'; end if;
  if p_keep is null or p_remove is null or p_keep = p_remove then raise exception 'choose two different teams' using errcode = '22023'; end if;
  -- Lock in a stable order so two organizers merging the same pair cannot deadlock.
  perform 1 from public.teams where id in (p_keep, p_remove) order by id for update;
  select * into v_keep from public.teams where id = p_keep;
  select * into v_remove from public.teams where id = p_remove;
  if v_keep.id is null or v_remove.id is null then raise exception 'team not found' using errcode = 'P0002'; end if;
  if v_keep.status <> 'approved' and v_remove.status = 'approved' then
    raise exception 'keep the approved team, or approve the kept team first' using errcode = '22023'; end if;
  if exists (select 1 from public.entries a join public.entries b on b.competition_id = a.competition_id
             where a.team_id = p_keep and b.team_id = p_remove) then
    raise exception 'both teams have an entry in the same competition; withdraw one entry first' using errcode = '22023'; end if;

  perform set_config('bos.merging', 'on', true);
  update public.entries set team_id = p_keep where team_id = p_remove;
  perform set_config('bos.merging', '', true);
  get diagnostics n_entries = row_count;
  update public.registrations set team_id = p_keep where team_id = p_remove;
  get diagnostics n_regs = row_count;
  update public.registration_competitions set team_id = p_keep where team_id = p_remove;
  get diagnostics n_regcomps = row_count;
  update public.fighters set team_id = p_keep where team_id = p_remove;
  get diagnostics n_fighters = row_count;
  update public.team_memberships set team_id = p_keep where team_id = p_remove;
  get diagnostics n_members = row_count;
  update public.events set host_team_id = p_keep where host_team_id = p_remove;
  get diagnostics n_hosts = row_count;

  -- Captains: keep one row per person.
  delete from public.team_roles r where r.team_id = p_remove and exists (select 1 from public.team_roles k where k.team_id = p_keep and k.user_id = r.user_id);
  update public.team_roles set team_id = p_keep where team_id = p_remove;
  get diagnostics n_roles = row_count;
  -- Affiliations are unique per (team, organization, relation): drop the removed team's copy of any the kept team already has.
  delete from public.team_affiliations a where a.team_id = p_remove and exists (
    select 1 from public.team_affiliations k where k.team_id = p_keep and k.organization_id = a.organization_id and k.relation = a.relation);
  update public.team_affiliations set team_id = p_keep where team_id = p_remove;
  get diagnostics n_affil = row_count;

  insert into public.team_merges (removed_team_id, removed_name, removed_slug, kept_team_id, was_public) values (p_remove, v_remove.name, v_remove.slug, p_keep, v_remove.status = 'approved');
  delete from public.teams where id = p_remove;
  perform private.audit(null, 'team.merged', p_keep::text, jsonb_build_object('removed', p_remove, 'removed_slug', v_remove.slug, 'removed_name', v_remove.name,
    'moved', jsonb_build_object('entries', n_entries, 'registrations', n_regs, 'registration_competitions', n_regcomps, 'fighters', n_fighters,
      'team_roles', n_roles, 'team_affiliations', n_affil, 'team_memberships', n_members, 'host_events', n_hosts)));
end $function$;

grant execute on function public.record_tie_decision(uuid, text, uuid[], text) to authenticated;
grant execute on function public.void_result(uuid, uuid, text) to authenticated;
grant execute on function public.build_schedule(uuid, jsonb, text, jsonb, integer) to authenticated;

create or replace trigger matches_clear_tie_decisions after update of queue_state, result, winner_entry_id, score_a, score_b on public.matches
  for each row when (old.stage in ('pool', 'round_robin') and (old.queue_state = 'final' or new.queue_state = 'final'))
  execute function private.clear_tie_decisions();
create or replace trigger result_revisions_no_change before update or delete on public.result_revisions for each row execute function private.result_revisions_append_only();
create or replace trigger entries_snapshot_team before insert or update of team_id on public.entries for each row execute function private.snapshot_entry_team();

-- =====================================================================================================================================
-- SECTION E: Pack 03 scoring commands (head marshal, idempotent finalization, Needs Review, paper recovery)
-- =====================================================================================================================================
CREATE OR REPLACE FUNCTION private.can_score(p_event uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select private.has_event_role(p_event, array['organizer', 'head_marshal', 'marshal', 'scorekeeper']) $function$;

CREATE OR REPLACE FUNCTION private.can_resolve_results(p_event uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select private.has_event_role(p_event, array['organizer', 'head_marshal']) $function$;

revoke execute on function private.can_resolve_results(uuid) from public;
grant execute on function private.can_resolve_results(uuid) to anon, authenticated;

CREATE OR REPLACE FUNCTION public.grant_event_role_by_email(p_event uuid, p_email text, p_role text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_user uuid;
begin
  if not private.is_organizer(p_event) then raise exception 'only an organizer can add staff' using errcode = '42501'; end if;
  if p_role not in ('organizer', 'head_marshal', 'marshal', 'scorekeeper', 'medic') then raise exception 'unknown role' using errcode = '22023'; end if;
  select id into v_user from auth.users where lower(email) = lower(p_email);
  if v_user is null then raise exception 'that person has not signed in to BuhurtOS yet' using errcode = 'P0002'; end if;
  insert into public.event_staff (event_id, user_id, role) values (p_event, v_user, p_role) on conflict do nothing;
  perform private.audit(p_event, 'staff.granted', p_role, jsonb_build_object('user', v_user));
end $function$;

CREATE OR REPLACE FUNCTION private.reopen_match_core(p_match uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_m public.matches; v_event uuid; v_next public.matches; v_third public.matches; v_loser uuid; v_slot text;
begin
  select * into v_m from public.matches where id = p_match for update;
  if not found then raise exception 'match not found' using errcode = 'P0002'; end if;
  v_event := private.event_of_match(p_match);
  if v_m.queue_state <> 'final' then return; end if;
  if char_length(coalesce(p_reason, '')) < 3 then raise exception 'say why the result is being reopened' using errcode = '22023'; end if;
  perform set_config('bos.reopen_reason', btrim(p_reason), true);
  v_loser := case v_m.result when 'a' then v_m.entry_b when 'b' then v_m.entry_a else null end;
  if v_m.next_match_id is not null then
    select * into v_next from public.matches where id = v_m.next_match_id for update;
    if v_next.queue_state = 'final' then raise exception 'the next match was already played; reopen that one first' using errcode = 'P0001'; end if;
    if v_m.stage = 'elimination' and v_loser is not null and v_next.stage = 'final' then
      select * into v_third from public.matches where competition_id = v_m.competition_id and stage = 'third_place' order by position, id limit 1 for update;
      if found then
        if v_third.queue_state = 'final' then raise exception 'the third-place match was already played; reopen that one first' using errcode = 'P0001'; end if;
        select case when count(*) = 0 then 'a' else 'b' end into v_slot from public.matches s
          where s.next_match_id = v_m.next_match_id and s.stage = 'elimination' and (s.position, s.id) < (v_m.position, v_m.id);
        if v_slot = 'a' and v_third.entry_a = v_loser then update public.matches set entry_a = null where id = v_third.id; end if;
        if v_slot = 'b' and v_third.entry_b = v_loser then update public.matches set entry_b = null where id = v_third.id; end if;
      end if;
    end if;
    if v_m.next_slot = 'a' and v_next.entry_a = v_m.winner_entry_id then update public.matches set entry_a = null where id = v_next.id; end if;
    if v_m.next_slot = 'b' and v_next.entry_b = v_m.winner_entry_id then update public.matches set entry_b = null where id = v_next.id; end if;
  end if;
  update public.matches set queue_state = 'scheduled', result = null, winner_entry_id = null, score_a = null, score_b = null, detail = '{}'::jsonb, finalized_at = null, version = version + 1 where id = p_match;
  perform private.audit(v_event, 'match.reopened', p_match::text, jsonb_build_object('reason', p_reason));
end $function$;

CREATE OR REPLACE FUNCTION public.reopen_match(p_match uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_organizer(private.event_of_match(p_match)) then raise exception 'only an organizer can reopen a result' using errcode = '42501'; end if;
  perform private.reopen_match_core(p_match, p_reason);
end $function$;

revoke execute on function private.reopen_match_core(uuid, text) from public, anon, authenticated;
grant execute on function public.reopen_match(uuid, text) to authenticated;

create table if not exists public.result_proposals (
  id uuid primary key,  -- the command id chosen by the device: the idempotency key
  match_id uuid not null references public.matches (id) on delete cascade,
  event_id uuid not null references public.events (id) on delete cascade,
  source text not null check (source in ('device', 'paper')),
  proposed_by uuid not null,
  schema_version integer not null,
  expected_version integer,
  result text not null check (result in ('a', 'b', 'draw')),
  score_a integer not null check (score_a >= 0),
  score_b integer not null check (score_b >= 0),
  detail jsonb not null default '{}'::jsonb,
  status text not null check (status in ('accepted', 'duplicate', 'conflict', 'stale', 'resolved_kept', 'resolved_replaced')),
  official_before jsonb,
  note text,
  resolved_by uuid,
  resolved_at timestamptz,
  resolution_note text,
  created_at timestamptz not null default now()
);
create index if not exists result_proposals_match_idx on public.result_proposals (match_id, created_at);
create index if not exists result_proposals_open_idx on public.result_proposals (event_id) where status = 'conflict';
alter table public.result_proposals enable row level security;
do $e$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public' and tablename = 'result_proposals' and policyname = 'result_proposals_read') then
    create policy result_proposals_read on public.result_proposals for select to authenticated using (proposed_by = auth.uid() or private.can_resolve_results(event_id));
  end if;
end $e$;
grant select on public.result_proposals to authenticated;

CREATE OR REPLACE FUNCTION public.list_result_conflicts(p_event uuid)
 RETURNS TABLE(proposal_id uuid, match_id uuid, competition_name text, round_label text, side_a text, side_b text, official_result text, official_score_a integer, official_score_b integer, proposed_result text, proposed_score_a integer, proposed_score_b integer, proposed_detail jsonb, proposed_by_name text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.can_resolve_results(p_event) then raise exception 'only the head marshal or an organizer can review result conflicts' using errcode = '42501'; end if;
  return query
  select p.id, p.match_id, k.name, m.round_label,
         coalesce((select t.name from public.entries e join public.teams t on t.id = e.team_id where e.id = m.entry_a), (select f.display_name from public.entries e join public.fighters f on f.id = e.fighter_id where e.id = m.entry_a), 'Side A'),
         coalesce((select t.name from public.entries e join public.teams t on t.id = e.team_id where e.id = m.entry_b), (select f.display_name from public.entries e join public.fighters f on f.id = e.fighter_id where e.id = m.entry_b), 'Side B'),
         m.result, m.score_a, m.score_b, p.result, p.score_a, p.score_b, p.detail, coalesce(private.person_name(p.proposed_by), 'Unnamed scorer'), p.created_at
  from public.result_proposals p join public.matches m on m.id = p.match_id join public.competitions k on k.id = m.competition_id
  where p.event_id = p_event and p.status = 'conflict' order by p.created_at;
end $function$;

CREATE OR REPLACE FUNCTION public.resolve_result_conflict(p_proposal uuid, p_decision text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_p public.result_proposals; v_m public.matches;
begin
  select * into v_p from public.result_proposals where id = p_proposal for update;
  if not found then raise exception 'conflict not found' using errcode = 'P0002'; end if;
  if not private.can_resolve_results(v_p.event_id) then raise exception 'only the head marshal or an organizer can resolve a result conflict' using errcode = '42501'; end if;
  if p_decision is null or p_decision not in ('keep_official', 'use_proposal') then raise exception 'decision must be keep_official or use_proposal' using errcode = '22023'; end if;
  if char_length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'say how this was decided' using errcode = '22023'; end if;
  if v_p.status <> 'conflict' then raise exception 'this conflict was already resolved' using errcode = 'P0001'; end if;
  select * into v_m from public.matches where id = v_p.match_id for update;
  if p_decision = 'use_proposal' then
    perform private.reopen_match_core(v_p.match_id, 'result conflict resolved: ' || btrim(p_note));
    perform public.finalize_match(v_p.match_id, v_p.result, v_p.score_a, v_p.score_b, v_p.detail, (select version from public.matches where id = v_p.match_id));
    update public.result_proposals set status = 'resolved_replaced', resolved_by = auth.uid(), resolved_at = now(), resolution_note = btrim(p_note) where id = p_proposal;
  else
    update public.result_proposals set status = 'resolved_kept', resolved_by = auth.uid(), resolved_at = now(), resolution_note = btrim(p_note) where id = p_proposal;
  end if;
  perform private.audit(v_p.event_id, 'result.conflict_resolved', v_p.match_id::text,
    jsonb_build_object('proposal', p_proposal, 'decision', p_decision, 'note', btrim(p_note), 'official_before', jsonb_build_object('result', v_m.result, 'score_a', v_m.score_a, 'score_b', v_m.score_b),
                       'proposal_result', jsonb_build_object('result', v_p.result, 'score_a', v_p.score_a, 'score_b', v_p.score_b)));
end $function$;

CREATE OR REPLACE FUNCTION public.enter_official_result(p_match uuid, p_result text, p_score_a integer, p_score_b integer, p_detail jsonb, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_m public.matches; v_event uuid; v_before jsonb; v_version integer; v_id uuid := gen_random_uuid();
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  select * into v_m from public.matches where id = p_match for update;
  if not found then raise exception 'match not found' using errcode = 'P0002'; end if;
  v_event := private.event_of_match(p_match);
  if not private.can_resolve_results(v_event) then raise exception 'only the head marshal or an organizer can enter an official result' using errcode = '42501'; end if;
  if char_length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'say where this result comes from (for example the paper sheet number)' using errcode = '22023'; end if;
  if v_m.entry_a is null or v_m.entry_b is null then raise exception 'both sides must be set before a result can be entered' using errcode = '22023'; end if;
  if p_result is null or p_result not in ('a', 'b', 'draw') then raise exception 'result must be a, b or draw' using errcode = '22023'; end if;
  if p_score_a is null or p_score_b is null or p_score_a < 0 or p_score_b < 0 then raise exception 'scores must be zero or more' using errcode = '22023'; end if;
  if v_m.queue_state = 'final' then
    if v_m.result = p_result and v_m.score_a = p_score_a and v_m.score_b = p_score_b then
      return jsonb_build_object('status', 'unchanged', 'version', v_m.version);
    end if;
    v_before := jsonb_build_object('result', v_m.result, 'score_a', v_m.score_a, 'score_b', v_m.score_b, 'detail', v_m.detail, 'version', v_m.version);
    perform private.reopen_match_core(p_match, 'corrected from paper: ' || btrim(p_note));
  end if;
  v_version := public.finalize_match(p_match, p_result, p_score_a, p_score_b, coalesce(p_detail, '{}'::jsonb), (select version from public.matches where id = p_match));
  insert into public.result_proposals (id, match_id, event_id, source, proposed_by, schema_version, expected_version, result, score_a, score_b, detail, status, official_before, note)
  values (v_id, p_match, v_event, 'paper', auth.uid(), 1, null, p_result, p_score_a, p_score_b, coalesce(p_detail, '{}'::jsonb), 'accepted', v_before, btrim(p_note));
  perform private.audit(v_event, 'result.paper_entered', p_match::text, jsonb_build_object('note', btrim(p_note), 'result', p_result, 'a', p_score_a, 'b', p_score_b, 'replaced', v_before));
  return jsonb_build_object('status', case when v_before is null then 'entered' else 'corrected' end, 'version', v_version);
end $function$;

grant execute on function public.list_result_conflicts(uuid) to authenticated;
grant execute on function public.resolve_result_conflict(uuid, text, text) to authenticated;
grant execute on function public.enter_official_result(uuid, text, integer, integer, jsonb, text) to authenticated;

-- =====================================================================================================================================
-- SECTION F: Pack 04 command compatibility window. submit_match_result is the final (Pack 03 + Pack 04) definition.
-- =====================================================================================================================================
CREATE OR REPLACE FUNCTION private.command_schema_ok(p_schema integer)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ select p_schema is not null and p_schema between 1 and 1 $function$;

revoke execute on function private.command_schema_ok(integer) from public;
grant execute on function private.command_schema_ok(integer) to anon, authenticated;

CREATE OR REPLACE FUNCTION public.submit_match_result(p_command uuid, p_match uuid, p_result text, p_score_a integer, p_score_b integer, p_detail jsonb, p_expected_version integer, p_schema integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_m public.matches; v_event uuid; v_prop public.result_proposals; v_status text; v_version integer;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_command is null then raise exception 'a command id is required' using errcode = '22023'; end if;
  if not private.command_schema_ok(p_schema) then raise exception 'this app version (command version %) is not supported by the server; reload the page. Your scoring is saved on this device and nothing was changed.', p_schema using errcode = '22023'; end if;

  select * into v_prop from public.result_proposals where id = p_command;
  if found then
    if v_prop.proposed_by <> auth.uid() then raise exception 'that command id belongs to someone else' using errcode = '42501'; end if;
    return jsonb_build_object('status', v_prop.status, 'version', (select version from public.matches where id = v_prop.match_id), 'repeat', true);
  end if;

  select * into v_m from public.matches where id = p_match for update;
  if not found then raise exception 'match not found' using errcode = 'P0002'; end if;
  v_event := private.event_of_match(p_match);
  if not private.can_score(v_event) then raise exception 'you cannot score this event' using errcode = '42501'; end if;
  if p_result is null or p_result not in ('a', 'b', 'draw') then raise exception 'result must be a, b or draw' using errcode = '22023'; end if;
  if p_score_a is null or p_score_b is null or p_score_a < 0 or p_score_b < 0 then raise exception 'scores must be zero or more' using errcode = '22023'; end if;
  if p_expected_version is null then raise exception 'the version you opened is required, reload the match' using errcode = '22023'; end if;

  if v_m.queue_state = 'final' then
    if v_m.result = p_result and v_m.score_a = p_score_a and v_m.score_b = p_score_b then
      v_status := 'duplicate';  -- another device already saved the same result: nothing to review
    else
      v_status := 'conflict';   -- a different official result exists: never overwrite, keep this one for the head marshal
    end if;
    insert into public.result_proposals (id, match_id, event_id, source, proposed_by, schema_version, expected_version, result, score_a, score_b, detail, status, official_before)
    values (p_command, p_match, v_event, 'device', auth.uid(), p_schema, p_expected_version, p_result, p_score_a, p_score_b, coalesce(p_detail, '{}'::jsonb), v_status,
            jsonb_build_object('result', v_m.result, 'score_a', v_m.score_a, 'score_b', v_m.score_b, 'detail', v_m.detail, 'version', v_m.version, 'finalized_at', v_m.finalized_at));
    if v_status = 'conflict' then
      perform private.audit(v_event, 'result.conflict', p_match::text, jsonb_build_object('proposal', p_command, 'official', v_m.result, 'proposed', p_result));
    end if;
    return jsonb_build_object('status', v_status, 'version', v_m.version);
  end if;

  if v_m.version <> p_expected_version then
    insert into public.result_proposals (id, match_id, event_id, source, proposed_by, schema_version, expected_version, result, score_a, score_b, detail, status)
    values (p_command, p_match, v_event, 'device', auth.uid(), p_schema, p_expected_version, p_result, p_score_a, p_score_b, coalesce(p_detail, '{}'::jsonb), 'stale');
    return jsonb_build_object('status', 'stale', 'version', v_m.version);
  end if;

  v_version := public.finalize_match(p_match, p_result, p_score_a, p_score_b, p_detail, p_expected_version);
  insert into public.result_proposals (id, match_id, event_id, source, proposed_by, schema_version, expected_version, result, score_a, score_b, detail, status)
  values (p_command, p_match, v_event, 'device', auth.uid(), p_schema, p_expected_version, p_result, p_score_a, p_score_b, coalesce(p_detail, '{}'::jsonb), 'accepted');
  return jsonb_build_object('status', 'accepted', 'version', v_version);
end $function$;

grant execute on function public.submit_match_result(uuid, uuid, text, integer, integer, jsonb, integer, integer) to authenticated;

-- =====================================================================================================================================
-- SECTION G: Pack 05 fighter identity and history views
-- =====================================================================================================================================
create table if not exists public.fighter_identity_reviews (
  id uuid primary key default gen_random_uuid(),
  fighter_id uuid not null references public.fighters (id) on delete cascade,       -- the record just created for an account
  candidate_id uuid not null references public.fighters (id) on delete cascade,     -- an existing record that may be the same person
  reason text not null default 'same_name' check (reason in ('same_name')),
  source text not null check (source in ('registration', 'team_join')),
  status text not null default 'open' check (status in ('open', 'distinct', 'duplicate')),
  note text,
  created_at timestamptz not null default now(),
  resolved_by uuid,
  resolved_at timestamptz,
  unique (fighter_id, candidate_id),
  check (fighter_id <> candidate_id)
);
create index if not exists fighter_identity_reviews_open_idx on public.fighter_identity_reviews (created_at) where status = 'open';
alter table public.fighter_identity_reviews enable row level security;   -- no policies: reachable only through the administrator functions
revoke all on public.fighter_identity_reviews from anon, authenticated;

CREATE OR REPLACE FUNCTION private.ensure_fighter_for_account(p_user uuid, p_name text, p_team uuid, p_source text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_fighter uuid; v_name text := left(btrim(p_name), 80);
begin
  perform pg_advisory_xact_lock(hashtextextended('fighter-account:' || p_user::text, 0));   -- two simultaneous accepts for one account run one after the other
  select fighter_id into v_fighter from public.fighter_accounts where user_id = p_user;
  if v_fighter is not null then return v_fighter; end if;
  insert into public.fighters (display_name, team_id) values (v_name, p_team) returning id into v_fighter;
  insert into public.fighter_accounts (fighter_id, user_id) values (v_fighter, p_user);
  insert into public.fighter_identity_reviews (fighter_id, candidate_id, source)
  select v_fighter, f.id, p_source from public.fighters f
  where f.id <> v_fighter and lower(btrim(f.display_name)) = lower(v_name)
    and not exists (select 1 from public.fighter_accounts a where a.fighter_id = f.id and a.user_id = p_user)
  on conflict do nothing;
  if found then
    perform private.audit(null, 'fighter.identity_review_opened', v_fighter::text, jsonb_build_object('source', p_source));
  end if;
  return v_fighter;
end $function$;

revoke execute on function private.ensure_fighter_for_account(uuid, text, uuid, text) from public, anon, authenticated;

CREATE OR REPLACE FUNCTION public.decide_registration(p_reg uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_reg public.registrations; v_rc record; v_fighter uuid; v_league text;
begin
  select * into v_reg from public.registrations where id = p_reg;
  if not found then raise exception 'registration not found' using errcode = 'P0002'; end if;
  if not private.is_organizer(v_reg.event_id) then raise exception 'only an organizer can decide registrations' using errcode = '42501'; end if;
  if p_status not in ('accepted', 'declined', 'pending') then raise exception 'unknown status' using errcode = '22023'; end if;

  if p_status = 'accepted' then
    select fighter_id into v_fighter from public.fighter_accounts where user_id = v_reg.user_id;
    if v_fighter is null then
      v_fighter := private.ensure_fighter_for_account(v_reg.user_id, v_reg.full_name, v_reg.team_id, 'registration');
    end if;
    update public.registrations set fighter_id = v_fighter where id = p_reg;
    for v_rc in select rc.*, c.category from public.registration_competitions rc join public.competitions c on c.id = rc.competition_id where rc.registration_id = p_reg loop
      select league into v_league from public.ref_categories where code = v_rc.category;
      if v_league = 'buhurt' then
        if v_rc.team_id is not null then
          insert into public.entries (competition_id, team_id) values (v_rc.competition_id, v_rc.team_id) on conflict (competition_id, team_id) do nothing;
        end if;
      else
        insert into public.entries (competition_id, fighter_id) values (v_rc.competition_id, v_fighter) on conflict (competition_id, fighter_id) do update set status = 'registered';
      end if;
    end loop;
  elsif v_reg.status = 'accepted' then
    -- Reversing an acceptance withdraws the person's own duel entries; team entries are left for the organizer.
    update public.entries set status = 'withdrawn' where fighter_id = v_reg.fighter_id and competition_id in (select competition_id from public.registration_competitions where registration_id = p_reg);
  end if;

  update public.registrations set status = p_status, decided_at = now() where id = p_reg;
  perform private.audit(v_reg.event_id, 'registration.' || p_status, p_reg::text);
end $function$;

CREATE OR REPLACE FUNCTION public.decide_team_join(p_request uuid, p_decision text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_req public.team_join_requests; v_team public.teams; v_name text; v_fighter uuid;
begin
  if auth.uid() is null then raise exception 'sign in required' using errcode = '28000'; end if;
  if p_decision not in ('approved', 'declined') then raise exception 'decision must be approved or declined' using errcode = '22023'; end if;
  select * into v_req from public.team_join_requests where id = p_request for update;
  -- A caller who may not decide cannot tell a missing request from someone else's.
  if not found or not private.can_manage_team(v_req.team_id) then raise exception 'you cannot decide this request' using errcode = '42501'; end if;
  if v_req.requester_id = auth.uid() then raise exception 'you cannot decide your own request' using errcode = '42501'; end if;
  if v_req.status <> 'pending' then raise exception 'this request has already been answered' using errcode = '22023'; end if;
  select * into v_team from public.teams where id = v_req.team_id;

  if p_decision = 'approved' then
    v_name := private.person_name(v_req.requester_id);
    if v_name is null then raise exception 'this person has no name on their profile yet' using errcode = '22023'; end if;
    select fighter_id into v_fighter from public.fighter_accounts where user_id = v_req.requester_id;
    if v_fighter is null then
      -- A NEW fighter record. Never matched to an existing public fighter by name: that is the later claim flow.
      v_fighter := private.ensure_fighter_for_account(v_req.requester_id, v_name, v_req.team_id, 'team_join');
    else
      update public.fighters set team_id = v_req.team_id where id = v_fighter and team_id is null;
    end if;
    if not exists (select 1 from public.team_memberships where fighter_id = v_fighter and team_id = v_req.team_id and (to_date is null or to_date >= current_date)) then
      insert into public.team_memberships (fighter_id, team_id, role, from_date) values (v_fighter, v_req.team_id, 'fighter', current_date);
    end if;
  end if;

  update public.team_join_requests set status = p_decision, decided_by = auth.uid(), decided_at = now() where id = p_request;
  insert into public.notifications (user_id, kind, payload)
  values (v_req.requester_id, 'team_join_decided', jsonb_build_object('request_id', p_request, 'team_id', v_team.id, 'team_name', v_team.name, 'team_slug', v_team.slug, 'decision', p_decision));
  -- Every manager's "new request" notification is done with.
  update public.notifications set read_at = coalesce(read_at, now()) where kind = 'team_join_requested' and payload ->> 'request_id' = p_request::text;
  perform private.audit(null, 'team.join_' || p_decision, v_team.id::text, jsonb_build_object('request', p_request));
end $function$;

CREATE OR REPLACE FUNCTION public.list_fighter_identity_reviews()
 RETURNS TABLE(review_id uuid, source text, created_at timestamp with time zone, new_fighter jsonb, candidate jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not private.is_owner() then raise exception 'only a platform administrator can review fighter identities' using errcode = '42501'; end if;
  return query
  select r.id, r.source, r.created_at,
    (select jsonb_build_object('id', f.id, 'name', f.display_name, 'team', t.name, 'has_account', true, 'created_at', f.created_at,
        'entries', (select count(*) from public.fighter_participation fp where fp.fighter_id = f.id), 'synthetic', private.is_synthetic('fighter', f.id))
       from public.fighters f left join public.teams t on t.id = f.team_id where f.id = r.fighter_id),
    (select jsonb_build_object('id', f.id, 'name', f.display_name, 'team', t.name, 'has_account', exists (select 1 from public.fighter_accounts a where a.fighter_id = f.id), 'created_at', f.created_at,
        'entries', (select count(*) from public.fighter_participation fp where fp.fighter_id = f.id), 'synthetic', private.is_synthetic('fighter', f.id),
        'sources', coalesce((select jsonb_agg(s.title) from public.record_sources rs join public.sources s on s.id = rs.source_id where rs.entity_type = 'fighter' and rs.entity_id = f.id), '[]'::jsonb))
       from public.fighters f left join public.teams t on t.id = f.team_id where f.id = r.candidate_id)
  from public.fighter_identity_reviews r where r.status = 'open' order by r.created_at;
end $function$;

CREATE OR REPLACE FUNCTION public.resolve_fighter_identity_review(p_review uuid, p_decision text, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_r public.fighter_identity_reviews;
begin
  if not private.is_owner() then raise exception 'only a platform administrator can review fighter identities' using errcode = '42501'; end if;
  if p_decision is null or p_decision not in ('distinct', 'duplicate') then raise exception 'decision must be distinct or duplicate' using errcode = '22023'; end if;
  if char_length(btrim(coalesce(p_note, ''))) < 3 then raise exception 'say how this was decided' using errcode = '22023'; end if;
  select * into v_r from public.fighter_identity_reviews where id = p_review for update;
  if not found then raise exception 'review not found' using errcode = 'P0002'; end if;
  if v_r.status <> 'open' then raise exception 'this review was already decided' using errcode = 'P0001'; end if;
  -- Nothing is merged here. "duplicate" records that a person judged the two records to be one human; the merge itself is a later, deliberate step.
  update public.fighter_identity_reviews set status = p_decision, note = btrim(p_note), resolved_by = auth.uid(), resolved_at = now() where id = p_review;
  perform private.audit(null, 'fighter.identity_review_' || p_decision, v_r.fighter_id::text, jsonb_build_object('candidate', v_r.candidate_id, 'note', btrim(p_note)));
end $function$;

grant execute on function public.list_fighter_identity_reviews() to authenticated;
grant execute on function public.resolve_fighter_identity_review(uuid, text, text) to authenticated;

create or replace view public.result_rows_all with (security_invoker = true) as
 SELECT r.competition_id, r.entry_id, r.final_place, COALESCE(r.points, (0)::numeric) AS points, k.name AS competition_name, k.category, k.gender, k.tier, k.structure,
        ev.id AS event_id, ev.slug AS event_slug, ev.name AS event_name, ev.event_type, ev.starts_on, ev.ends_on AS event_ends_on, ev.season_id,
        COALESCE(ev.organization_id, se.organization_id) AS organization_id, e.team_id, e.fighter_id AS entry_fighter_id,
        private.is_synthetic('event', ev.id) AS synthetic, COALESCE(e.team_name_at_event, t.name) AS team_name_at_event, t.name AS team_current_name, t.slug AS team_current_slug
   FROM (((((results r JOIN entries e ON ((e.id = r.entry_id))) JOIN competitions k ON ((k.id = r.competition_id))) JOIN events ev ON ((ev.id = k.event_id)))
        LEFT JOIN seasons se ON ((se.id = ev.season_id))) LEFT JOIN teams t ON ((t.id = e.team_id)))
  WHERE r.final_place IS NOT NULL;
create or replace view public.fighter_results_all with (security_invoker = true) as
 SELECT fp.fighter_id, rr.* FROM (result_rows_all rr JOIN fighter_participation fp ON ((fp.entry_id = rr.entry_id)));
create or replace view public.team_results_all with (security_invoker = true) as
 SELECT rr.* FROM result_rows_all rr WHERE rr.team_id IS NOT NULL;
grant select on public.result_rows_all, public.fighter_results_all, public.team_results_all to anon, authenticated;

-- =====================================================================================================================================
-- SECTION H: commit only if the result is exactly branch fd746d4 (schema objects and anon/authenticated privileges). Otherwise everything
-- above is rolled back and the database is unchanged.
-- =====================================================================================================================================
do $final$
declare v_schema text; v_grants text;
begin
  select (select count(*) || '|' || md5(string_agg(line, E'\n' order by line collate "C")) from (select regexp_replace(line, '\s+', ' ', 'g') as line from (
    select 'table ' || c.relnamespace::regnamespace || '.' || c.relname || ' rls=' || c.relrowsecurity as line
      from pg_class c where c.relkind = 'r' and c.relnamespace::regnamespace::text in ('public', 'private')
    union all
    select 'column ' || c.relnamespace::regnamespace || '.' || c.relname || '.' || a.attname || ' ' || format_type(a.atttypid, a.atttypmod) || case when a.attnotnull then ' not null' else '' end
      from pg_attribute a join pg_class c on c.oid = a.attrelid
      where c.relkind in ('r', 'p') and a.attnum > 0 and not a.attisdropped and c.relnamespace::regnamespace::text in ('public', 'private')
    union all
    select 'constraint ' || c.conrelid::regclass || ' ' || c.conname || ' ' || pg_get_constraintdef(c.oid)
      from pg_constraint c where c.connamespace::regnamespace::text in ('public', 'private')
    union all
    select 'index ' || i.schemaname || '.' || i.tablename || ' ' || regexp_replace(i.indexdef, '^CREATE (UNIQUE )?INDEX \S+ ', 'CREATE \1INDEX ')
      from pg_indexes i where i.schemaname in ('public', 'private')
    union all
    select 'policy ' || p.schemaname || '.' || p.tablename || ' ' || p.policyname || ' ' || p.cmd || ' roles=' || array_to_string(p.roles, ',') || ' using=' || coalesce(p.qual, '') || ' check=' || coalesce(p.with_check, '')
      from pg_policies p where p.schemaname in ('public', 'private')
    union all
    select 'function ' || n.nspname || '.' || p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ') secdef=' || p.prosecdef || ' ' || md5(btrim(regexp_replace(regexp_replace(pg_get_functiondef(p.oid), '--[^\n]*', '', 'g'), '\s+', ' ', 'g')))
      from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public', 'private') and p.prokind in ('f', 'p')
    union all
    select 'view ' || c.relnamespace::regnamespace || '.' || c.relname || ' opts=' || coalesce(array_to_string(c.reloptions, ','), '') || ' ' || md5(btrim(regexp_replace(regexp_replace(pg_get_viewdef(c.oid), '--[^\n]*', '', 'g'), '\s+', ' ', 'g')))
      from pg_class c where c.relkind in ('v', 'm') and c.relnamespace::regnamespace::text in ('public', 'private')
    union all
    select 'trigger ' || c.relnamespace::regnamespace || '.' || c.relname || ' ' || t.tgname || ' ' || md5(btrim(regexp_replace(regexp_replace(pg_get_triggerdef(t.oid), '--[^\n]*', '', 'g'), '\s+', ' ', 'g')))
      from pg_trigger t join pg_class c on c.oid = t.tgrelid where not t.tgisinternal and c.relnamespace::regnamespace::text in ('public', 'private')
  ) x) y) into v_schema;
  select (with o as (
    select 'f ' || p.oid::regprocedure::text as k, has_function_privilege('anon', p.oid, 'execute')::int::text || has_function_privilege('authenticated', p.oid, 'execute')::int::text as v
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname in ('public', 'private') and p.prokind in ('f', 'p')
    union all
    select 't ' || c.oid::regclass::text, (select string_agg(has_table_privilege(r, c.oid, pr)::int::text, '' order by r, pr) from unnest(array['anon', 'authenticated']) r, unnest(array['select', 'insert', 'update', 'delete']) pr)
    from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname in ('public', 'private') and c.relkind in ('r', 'v', 'm')
    union all select 's private', has_schema_privilege('anon', 'private', 'usage')::int::text || has_schema_privilege('authenticated', 'private', 'usage')::int::text
  ) select count(*) || '|' || md5(string_agg(k || '=' || v, ',' order by k collate "C")) from o) into v_grants;
  if v_schema <> '1037|43986d8c12e7a5bbab04485e924e9a69' or v_grants <> '205|b5e6b055d964385036f10a98f3910e16' then
    raise exception 'ROLLED BACK: the result does not match branch fd746d4 (schema % / grants %, expected % / %). Nothing was changed.',
      v_schema, v_grants, '1037|43986d8c12e7a5bbab04485e924e9a69', '205|b5e6b055d964385036f10a98f3910e16';
  end if;
  raise notice 'Schema and privileges now match branch fd746d4 (schema %, grants %).', v_schema, v_grants;
end $final$;

commit;

-- =====================================================================================================================================
-- VERIFICATION (after commit). Behavioural and permission checks with fictional fixtures inside a sub-transaction that is always rolled
-- back; the result table below is the output of this script. Same content as supabase/manual/hosted_verify_packs_01_05.sql.
-- =====================================================================================================================================

create or replace function pg_temp.bos_verify_packs_01_05()
returns table(pack text, check_name text, result boolean, detail text)
language plpgsql as $V$
#variable_conflict use_column
declare
  v_rows jsonb := '[]'::jsonb;
  v_msg text; v_ctx text;
begin
  begin
    -- ------------------------------------------------------------------------------------------------ helpers (rolled back with everything else)
    create schema zzv;
    create table zzv.log (n serial primary key, pack text, check_name text, ok boolean, detail text);
    create table zzv.kv (k text primary key, v text);
    create function zzv.id(k text) returns uuid language sql immutable as $h$ select md5('bos-verify:' || k)::uuid $h$;
    create function zzv.pack(p text) returns text language sql as $h$ select set_config('zzv.pack', p, true) $h$;
    create function zzv.as_admin() returns void language plpgsql as $h$
    begin reset role; perform set_config('request.jwt.claim.sub', '', true); perform set_config('request.jwt.claims', '', true); end $h$;
    create function zzv.as_anon() returns void language plpgsql as $h$
    begin reset role; perform set_config('request.jwt.claim.sub', '', true); perform set_config('request.jwt.claims', '{"role":"anon"}', true); set local role anon; end $h$;
    create function zzv.as_user(u text) returns void language plpgsql as $h$
    begin
      reset role;
      perform set_config('request.jwt.claim.sub', zzv.id(u)::text, true);
      perform set_config('request.jwt.claims', json_build_object('sub', zzv.id(u), 'role', 'authenticated')::text, true);
      set local role authenticated;
    end $h$;
    create function zzv.rec(p_ok boolean, p_label text, p_detail text) returns void language sql as $h$
      insert into zzv.log (pack, check_name, ok, detail) values (current_setting('zzv.pack', true), p_label, coalesce(p_ok, false), p_detail)
    $h$;
    -- q: run a query, compare its single value (as text) with the expected text. An error is a FALSE row, never an abort.
    create function zzv.q(p_label text, p_sql text, p_want text) returns void language plpgsql as $h$
    declare v text;
    begin
      begin execute 'select (' || p_sql || ')::text' into v;
      exception when others then perform zzv.rec(false, p_label, 'error ' || sqlstate || ': ' || sqlerrm); return; end;
      perform zzv.rec(v is not distinct from p_want, p_label, 'got ' || coalesce(v, 'null') || case when v is distinct from p_want then ', expected ' || coalesce(p_want, 'null') else '' end);
    end $h$;
    -- err: the statement must fail, with the given SQLSTATE when one is given.
    create function zzv.err(p_label text, p_sql text, p_state text) returns void language plpgsql as $h$
    begin
      begin execute p_sql;
      exception when others then
        perform zzv.rec(p_state is null or sqlstate = p_state, p_label, 'refused ' || sqlstate || ': ' || left(sqlerrm, 160)); return;
      end;
      perform zzv.rec(false, p_label, 'NOT refused: the statement succeeded');
    end $h$;
    -- ok: the statement must succeed.
    create function zzv.ok(p_label text, p_sql text) returns void language plpgsql as $h$
    begin
      begin execute p_sql;
      exception when others then perform zzv.rec(false, p_label, 'error ' || sqlstate || ': ' || left(sqlerrm, 160)); return; end;
      perform zzv.rec(true, p_label, 'allowed');
    end $h$;
